-- Fakt kartochkalari orqa tomonining ruscha matni — 72-partiya:
-- Pirimqul Qodirov, Qaffol Shoshiy, Qori-Niyoziy.

UPDATE fact_cards SET detail_ru = 'Пиримкул Кадыров родился 25 октября 1928 года в селении Кенгкуль Шахристанского района нынешней Республики Таджикистан. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2258;
UPDATE fact_cards SET detail_ru = 'В 1951 году он окончил востоковедческий факультет Среднеазиатского университета. В том же году был напечатан первый его рассказ «Студенты». Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2259;
UPDATE fact_cards SET detail_ru = 'Роман «Звёздные ночи» (1979) изображает жизнь великого поэта и государственного деятеля Захириддина Мухаммада Бабура. Роман был написан несмотря на то, что советская идеология в 70-е годы сильно противилась исторической теме. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2260;
UPDATE fact_cards SET detail_ru = '«Перевал поколений» (1989) — исторический роман, изданный как продолжение романа «Звёздные ночи». Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2261;
UPDATE fact_cards SET detail_ru = 'Его перу принадлежат такие сочинения, как «Три корня» (1958), «Моё достоинство» (1961), «Чёрные глаза» (1966), «Свобода» (1968), «Наследие» (1974), «Алмазный пояс» (1976) и «Клич матери-сокола» (2000). Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2262;
UPDATE fact_cards SET detail_ru = 'В 1954–1963 годах он был консультантом по узбекской словесности в Союзе писателей СССР, а в 1963–1983 годах — старшим научным сотрудником Института языка и литературы Академии наук Узбекистана. Есть у него и научные работы «Язык и душа» (1972), «Народный язык и реалистическая проза» (1973). Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2263;
UPDATE fact_cards SET detail_ru = 'В 1978 году он был удостоен звания заслуженного деятеля культуры Узбекистана, а в 1988-м — народного писателя Узбекистана. Он награждён Государственной премией имени Хамзы (1981), медалью «Шухрат» (1994) и орденом «Эл-юрт хурмати» (1998). Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2264;
UPDATE fact_cards SET detail_ru = 'Пиримкул Кадыров умер в 2010 году. Точные день и место его смерти в статье-источнике не указаны. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2265;

UPDATE fact_cards SET detail_ru = 'Каффаль Шаши родился в 903 году в городе Шаш (нынешний Ташкент), в семье ремесленника. Нисба «Шаши» указывает на его принадлежность к этому городу. Источник: Национальная энциклопедия Узбекистана (ziyouz.com).' WHERE id = 2266;
UPDATE fact_cards SET detail_ru = 'По источникам, он изготовил крохотный замок с ключом весом в полграмма. За это ему и было дано прозвище «Каффаль», то есть «замочник». Источник: Национальная энциклопедия Узбекистана (ziyouz.com).' WHERE id = 2267;
UPDATE fact_cards SET detail_ru = 'Он учился у известного знатока хадисов и богослова Хайсама ибн Кулайба. Был он также учеником знаменитого имама Абуль Аббаса Ахмада ибн Умара ибн ас-Сурайджи (850–918). Источник: Национальная энциклопедия Узбекистана (ziyouz.com).' WHERE id = 2268;
UPDATE fact_cards SET detail_ru = 'Он побывал в Самарканде, Бухаре и Термезе, изучая наследие учёных, затем совершил долгое странствие по странам арабского Востока и немалое время жил в Багдаде. В халифате он исполнял разные должности и поручения. Источник: Национальная энциклопедия Узбекистана (ziyouz.com).' WHERE id = 2269;
UPDATE fact_cards SET detail_ru = 'Каффаль Шаши был одним из ведущих учёных шафиитского толка — знатоком хадисов, правоведом, языковедом и поэтом. За глубокие знания и огромные труды его называли «Имам аль-Кабир» («Великий имам»), а в народе он известен под именем «Хазрати Имам» (Хастимом). Источник: Национальная энциклопедия Узбекистана (ziyouz.com).' WHERE id = 2270;
UPDATE fact_cards SET detail_ru = 'Он написал такие сочинения по законоведению и логике, как «Нрав судьи», «Одоб аль-бахс» («Благонравие в споре»), «Хусн-и джадаль» («Красота диалектики»), и они были известны в исламском мире. Отдельные отрывки его стихов сохранились через книгу учёного Таджиддина ас-Субки «Табакат аш-Шафиия». Источник: Национальная энциклопедия Узбекистана (ziyouz.com).' WHERE id = 2271;
UPDATE fact_cards SET detail_ru = 'Сын Каффаля Шаши, Касим Шаши (X век), тоже был правоведом, и у него учились правоведы Хорасана и Ирака. Его сочинение «Ат-Такриб фи-ль-фуру» признано одной из почитаемых книг шафиитского толка. Источник: Национальная энциклопедия Узбекистана (ziyouz.com).' WHERE id = 2272;
UPDATE fact_cards SET detail_ru = 'Каффаль Шаши умер в 976 году в Ташкенте. Над его могилой в 1541–1542 годах зодчим Гулямом Хусейном был построен мавзолей, и позже на основе этого мавзолея сложился известный ташкентский комплекс Хазрати Имам. Источник: Национальная энциклопедия Узбекистана (ziyouz.com).' WHERE id = 2273;

UPDATE fact_cards SET detail_ru = 'Ташмухаммад Кары-Ниязи родился 9 февраля 1897 года в городе Худжанде. Позже его жизнь и деятельность были связаны с Ферганой и Ташкентом. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2052;
UPDATE fact_cards SET detail_ru = 'В 1917 году Кары-Ниязи основал в Фергане первую узбекскую школу нового типа. В 1920 году эта школа была обращена в Ферганский областной учебно-воспитательный техникум, и Кары-Ниязи стал его директором. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2053;
UPDATE fact_cards SET detail_ru = 'Кары-Ниязи окончил Среднеазиатский университет в 1929 году, в 1931-м получил звание профессора, а в 1931–1933 годах был ректором этого университета. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2054;
UPDATE fact_cards SET detail_ru = 'Кары-Ниязи — автор первых на узбекском языке учебников по элементарной и высшей математике. В его книге воспоминаний «Школа жизни» изображён научный и культурный подъём в республике; с 1939 года он был и главным редактором журнала «Фан ва турмуш». Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2055;
UPDATE fact_cards SET detail_ru = 'В 1940–1943 годах Кары-Ниязи был председателем президиума Узбекистанского филиала Академии наук СССР. Когда в 1943 году была учреждена Академия наук Узбекистана, он был избран её первым президентом и работал в этой должности в 1943–1947 годах. В том же 1943 году он стал академиком. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2056;
UPDATE fact_cards SET detail_ru = 'В 1937–1938 годах Кары-Ниязи был народным комиссаром просвещения Узбекистана и председателем Комитета наук. С 1939 года он работал заведующим кафедрой математики в Ташкентском институте инженеров ирригации и механизации. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2057;
UPDATE fact_cards SET detail_ru = 'В 1939 году Кары-Ниязи стал доктором физико-математических наук и заслуженным деятелем науки Узбекистана. В 1952 году он был награждён Государственной премией, а в 1967-м получил звание Героя Труда. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2058;
UPDATE fact_cards SET detail_ru = 'Он умер 18 марта 1970 года в Ташкенте и в том же году был удостоен Государственной премии Узбекистана имени Беруни. Его имя носят Научно-исследовательский институт педагогических наук Узбекистана, одна из улиц Ташкента и школа № 206. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2059;
